SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/df264aefc4373c3f610c2f0bb525ac26f65cd07c/content/books/zizhi-tongjian/vol-286/year-0947/part-13/sources/library/jiuwudaishi-099-heyang-april/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002430；EPUB电子本，纸本及异文待核", "id": "73d07631-ce73-5399-890a-1e917e6cc33b"}, {"title": "宋史·巻二百五十二", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/df264aefc4373c3f610c2f0bb525ac26f65cd07c/content/books/zizhi-tongjian/vol-286/year-0947/part-13/sources/library/songshi-252-wu-xingde-heyang/source.txt", "note": "《宋史》巻二百五十二，段落 songshi-9c6e46fee832-p057359；EPUB电子本，纸本及异文待核", "id": "8f9c4bd5-ea97-571d-a22a-6e8775dae5da"}, {"title": "宋史·巻二百五十二", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/df264aefc4373c3f610c2f0bb525ac26f65cd07c/content/books/zizhi-tongjian/vol-286/year-0947/part-13/sources/library/songshi-252-wu-xingde-origin/source.txt", "note": "《宋史》巻二百五十二，段落 songshi-9c6e46fee832-p057358；EPUB电子本，纸本及异文待核", "id": "29a2500e-9b3e-525c-b979-f9cf0af60b8c"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f2c47323ed0300cae625304e870298722acfa1ce/content/books/zizhi-tongjian/vol-286/year-0947/part-12/sources/library/tongjian-286-947-return-april/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003401；电子底本待考，分段待核", "id": "a6f8049e-ea12-5160-a527-1d0e42e1c89d"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f2c47323ed0300cae625304e870298722acfa1ce/content/books/zizhi-tongjian/vol-286/year-0947/part-12/sources/library/jiuwudaishi-099-april-appointments/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002429；EPUB电子本，纸本及异文待核", "id": "e67c334a-9e54-5f26-8a7b-aad44d76df40"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "张砺", "aliases": ["張礪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张砺。", "biography": null, "status": "draft", "id": "9f51ea48-71ce-5c98-a3af-c7854041f72f"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "折从远", "aliases": ["折從遠", "折从阮", "折從阮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，府州刺史。后晋割让北地后，府州归属契丹。他据险抵制契丹迁民，后奉石重贵命令攻入契丹境内、拔十余寨，944年六月戊午任府州团练使。《新五代史》明确其后因避汉高祖名改称折从阮，字可久。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "500d7480-2e3a-5553-9370-8e4295db3cc1"}, {"name": "刘铢", "aliases": ["劉銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "陕地人，任河东左都押牙。947年刘知远任命他为河阳节度使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "bcd8da9c-9e21-53c2-a6be-7a6d37b61a32"}, {"name": "耿崇美", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十二月杜重威降后，奉命到易州诱说守军投降，并杀死刺史郭璘。生卒年未载。", "biography": null, "status": "draft", "id": "60458ef5-e4bc-5d29-b338-25090e903595"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "王守恩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王建立的儿子，与张从恩是姻亲。947年在上党，以左骁卫大将军身份被张从恩暂派为巡检使，协助赵行迁。姻亲具体双方未明，不补具体婚配，生卒年未载。", "biography": null, "status": "draft", "id": "72fe9a16-4716-54d0-bc82-5e7feadc013e"}, {"name": "高允权", "aliases": ["高允權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高万金之子。947年延州军队攻周密，高允权获推为留后、据西城。《通鉴》称录事参军，《新五代史》追记开运时任肤施令、罢后居家，任职时点及写法分别保留。生卒年暂未录入。", "biography": null, "status": "draft", "id": "be6f380e-7cd3-5e5e-87d2-900104d55f65"}, {"name": "郑廉", "aliases": ["鄭廉", "郑谦", "鄭謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "岢岚军使。947年获任忻州刺史，兼忻、代二州义军都部署。《旧五代史》同职同事作郑谦，《资治通鉴》后句也用谦字，保留异写；所领节度军号存在差异。生卒年未载。", "biography": null, "status": "draft", "id": "be1a64a6-309b-5211-905e-16b9f5a43d88"}, {"name": "阎万进", "aliases": ["閻萬進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州人，任沿河巡检使。947年获任岚州刺史，兼岚、宪二州义军都制置使。所领节度军号各书有差异。生卒年未载。", "biography": null, "status": "draft", "id": "ae4f1790-0288-57d3-97af-eda606e08873"}, {"name": "武行德", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州榆次人。947年受契丹命运送晋朝铠甲兵器，途中与军士夺取兵器、杀契丹监军，继而占据河阳。生卒年尚未录入。", "biography": null, "status": "draft", "id": "e0ed92f8-edb4-574b-83af-85088429a093"}, {"name": "崔廷勋", "aliases": ["崔廷勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河内人。947年正月《资治通鉴》称他为大同节度使兼侍中，耶律德光派他率兵看守迁到封禅寺的石重贵及家人。《旧五代史》称为蕃大将崔廷勋，未另建同名人；生卒年未载。", "biography": null, "status": "draft", "id": "43995ba6-a8ce-5d3a-86dd-43d3def50195"}, {"name": "武行友", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武行德的弟弟。947年受武行德派遣，携蜡封表章经小路前往晋阳。生卒年未载。", "biography": null, "status": "draft", "id": "4b99493b-be61-56ba-9d53-19a33fed5a71"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
